#include <stdio.h>

int main() {
    int marks[] = {72, 85, 90, 64, 79};
    int count = sizeof(marks) / sizeof(marks[0]);
    int sum = 0;
    for (int i = 0; i < count; i++) {
        sum += marks[i];
    }
    printf("Sum: %d\n", sum);
    printf("Average: %.2f\n", (double)sum / count);
    return 0;
}
